package com.simpletoob.app;
import android.app.AlertDialog;
import android.content.Intent;
import android.os.Bundle;
import android.widget.*;
import java.util.*;
public final class ImportSettingsActivity extends BaseActivity {
    private LinearLayout panel;private TextView status;
    @Override public void onCreate(Bundle b){super.onCreate(b);LinearLayout root=ui.column();ui.root(root);root.addView(ui.toolbar("Account imports",this::finish));ScrollView scroll=new ScrollView(this);panel=ui.column();ui.padded(panel);scroll.addView(panel);root.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));show();}
    @Override protected void onImportStatusChanged(){if(status!=null)status.setText(app.imports.status());}
    @Override protected void onImportsChanged(){if(panel!=null)show();}
    private void show(){panel.removeAllViews();boolean signed=app.sessions.present();panel.addView(ui.heading("Keep your library together",22));panel.addView(ui.note("Imports copy YouTube subscriptions and playlists into your regular local lists. Local edits are not uploaded. Automatic imports pause when signed out."));status=ui.note(app.imports.status());panel.addView(status);if(!signed)panel.addView(ui.button("Sign in to YouTube",true,()->WebSessionActivity.signIn(this)));Button all=ui.button("Import subscriptions & playlists",true,()->app.imports.start(true,true,null));all.setEnabled(signed);panel.addView(all);ui.space(panel,12);
        category("Subscriptions","subs",true);category("Playlists","lists",false);ui.space(panel,16);
        panel.addView(ui.item("settings","Import behavior",app.imports.mirror()?"Mirror previous imports; keep local-only items":"Merge imports; keep local items",()->new AlertDialog.Builder(this).setTitle("Import behavior").setSingleChoiceItems(new String[]{"Merge · keep missing channels/playlists","Mirror · remove missing imported collections"},app.imports.mirror()?1:0,(d,i)->{app.imports.mirror(i==1);d.dismiss();show();}).setNegativeButton("Cancel",null).show()));
        panel.addView(ui.note("Unedited imported playlists refresh their contents. Edited copies are kept as-is until you explicitly allow a refresh from their playlist menu. Mirror never deletes local-only subscriptions or playlists."));Switch wifi=new Switch(this);wifi.setText("Imports on unmetered networks only");wifi.setTextColor(ui.text);wifi.setChecked(app.imports.unmetered());wifi.setOnCheckedChangeListener((v,on)->app.imports.unmetered(on));panel.addView(wifi);panel.addView(ui.note("Background intervals have a 15-minute minimum. Android can delay jobs for battery and network conditions. Settings apply to this local profile."));panel.addView(ui.quiet("Stop current import",()->{app.imports.cancel();status.setText("Import stopped; completed local copies kept");}));
    }
    private void category(String label,String kind,boolean subs){ui.space(panel,18);panel.addView(ui.heading(label,19));Switch launch=new Switch(this);launch.setText("Import on app launch");launch.setTextColor(ui.text);launch.setChecked(app.imports.launch(kind));launch.setOnCheckedChangeListener((v,on)->app.imports.launch(kind,on));panel.addView(launch);int minutes=app.imports.minutes(kind);panel.addView(ui.item("refresh","Automatic interval",minutes==0?"Manual / launch only":minutes+" minutes",()->interval(kind)));Button manual=ui.quiet("Import "+label.toLowerCase(Locale.ROOT)+" now",()->app.imports.start(subs,!subs,null));manual.setEnabled(app.sessions.present());panel.addView(manual);long last=app.imports.last(kind);panel.addView(ui.note(last==0?"No completed import for this account":("Last completed: "+java.text.DateFormat.getDateTimeInstance().format(new Date(last)))));}
    private void interval(String kind){new AlertDialog.Builder(this).setTitle("Import interval").setItems(new String[]{"Off","15 minutes","30 minutes","1 hour","6 hours","12 hours","Daily","Custom minutes"},(d,i)->{if(i<7){app.imports.interval(kind,new int[]{0,15,30,60,360,720,1440}[i]);show();}else{EditText input=ui.input("15–10,080 minutes");input.setInputType(android.text.InputType.TYPE_CLASS_NUMBER);AlertDialog dialog=new AlertDialog.Builder(this).setTitle("Custom import interval").setView(input).setNegativeButton("Cancel",null).setPositiveButton("Save",null).create();dialog.setOnShowListener(v->dialog.getButton(-1).setOnClickListener(x->{try{app.imports.interval(kind,Integer.parseInt(input.getText().toString()));dialog.dismiss();show();}catch(Exception e){input.setError("Use 15–10,080 minutes");}}));dialog.show();}}).show();}
    @Override protected void onResume(){super.onResume();if(panel!=null)show();}
}
